"""Complete 24 original substance-use disorder questions."""
from create_psych_alcohol import rows,q,AW,AU,OU,ref
from qbank_authoring import finalize
ST=ref('ASAM/AAAP stimulant-use disorder guideline','https://pmc.ncbi.nlm.nih.gov/articles/PMC11105801/')
TO=ref('WHO tobacco cessation clinical treatment guideline','https://www.who.int/publications/i/item/9789240096431')

q('A patient after stopping heroin develops yawning, lacrimation, mydriasis, piloerection, abdominal cramps and diarrhea. Which syndrome is most likely?', 'Opioid withdrawal',[
 ('Opioid intoxication','Intoxication more typically produces miosis and respiratory/CNS depression.'),('Antimuscarinic toxicity','That more often causes dryness, urinary retention and reduced bowel activity.'),('Alcohol withdrawal delirium','The autonomic overlap does not replace the distinctive opioid pattern or establish delirium.')],
 'Direction of opioid exposure changes the clinical pattern','**Withdrawal produces autonomic and gastrointestinal activation.**',['Severity depends on the opioid, exposure and time since reduction.','Other illness and mixed withdrawal can coexist.'],'**Offer evidence-based withdrawal and continuing OUD treatment.**',['Assess hydration, pregnancy and medical comorbidity.','Do not mistake symptom relief alone for a complete recovery plan.'],[['Intoxication','Depressed breathing/awareness'],['Withdrawal','Mydriasis, GI and autonomic activation'],['Care','Symptoms plus ongoing OUD treatment']],[OU],style='clinical_scenario')

q('What is the relevant receptor pharmacology of buprenorphine in opioid-use-disorder treatment?', 'High-affinity partial mu-opioid receptor agonism',[
 ('Pure mu antagonism','This describes naltrexone rather than buprenorphine.'),('A full mu agonist identical to methadone','Its partial-agonist profile differs.'),('A GABA-A positive modulator','This is not its primary therapeutic mechanism.')],
 'High affinity and partial agonism explain both benefit and initiation challenges','**Buprenorphine can suppress withdrawal and craving while having a different dose-effect profile from full agonists.**',['It can displace other opioids from receptors.','Sedatives and other respiratory risk factors still matter.'],'**Use an individualized induction and maintenance plan.**',['Do not interpret a relative ceiling effect as no overdose risk.','Provide overdose education and access to rescue naloxone.'],[['Buprenorphine','Partial mu agonist'],['Methadone','Full mu agonist'],['Naltrexone','Antagonist']],[OU])

q('Why can standard buprenorphine initiation precipitate withdrawal if given too soon after a full opioid agonist?', 'It can displace the full agonist while providing less receptor activation',[
 ('It immediately converts all circulating opioid to naloxone','No such metabolic conversion occurs.'),('It is an irreversible enzyme inhibitor of opioid synthesis','Its action is receptor binding, not enzyme inhibition.'),('It causes withdrawal only through an allergic reaction','Precipitated withdrawal is a pharmacological displacement phenomenon.')],
 'Timing and the initiation strategy matter','**High affinity can abruptly reduce net mu-receptor activation.**',['Standard induction generally uses an appropriate withdrawal assessment.','Fentanyl exposure and other clinical factors can complicate timing.'],'**Use an experienced individualized induction pathway.**',['Selected low-dose strategies have different protocols and evidence limits.','Do not use a fixed clock interval as the sole safety criterion.'],[['High affinity','Displacement'],['Partial agonism','Lower activation than displaced full agonist'],['Prevention','Appropriate assessment and strategy']],[OU,ref('ASAM buprenorphine considerations for high-potency synthetic opioid exposure','https://doi.org/10.1097/ADM.0000000000001202')])

q('Which cardiac safety issue is especially relevant when prescribing methadone?', 'QT prolongation and torsades risk in susceptible patients',[
 ('A predictable short-QT syndrome in every patient','This is not the characteristic concern.'),('No interaction risk because methadone is used therapeutically','Other drugs and patient factors can increase risk.'),('A guarantee that a normal baseline ECG excludes all later risk','Dose, electrolytes and co-medications can change.')],
 'Effective OUD treatment still needs individualized safety review','**Methadone is a full agonist with a long and variable half-life.**',['Accumulation can cause delayed sedation and respiratory harm during titration.','QT risk increases with relevant drugs, electrolytes and cardiac factors.'],'**Use careful initiation and appropriate ECG/electrolyte assessment.**',['Review all sedatives and interactions.','Balance risk management against the substantial benefits of effective treatment.'],[['Mechanism','Full mu agonist'],['Titration','Accumulation risk'],['Cardiac','QT-related risk']],[OU])

q('Before starting extended-release naltrexone for OUD, which issue is essential?', 'Confirm an appropriate opioid-free state and absence of physiological dependence using the recommended assessment',[
 ('Start immediately after any full-agonist dose because antagonism prevents withdrawal','It can precipitate severe withdrawal.'),('Continue routine opioid analgesics without any interaction discussion','Naltrexone blocks opioid effects and complicates analgesia.'),('Use it as the same type of maintenance agonist as methadone','It is an antagonist, not an agonist.')],
 'Antagonist induction differs from agonist induction','**Naltrexone can displace/block opioid effects in a dependent patient.**',['The required interval varies with the opioid and clinical context.','A simple negative routine screen may not exclude every opioid exposure.'],'**Use a structured specialist initiation plan.**',['Discuss pain management and overdose vulnerability after treatment lapses.','Do not force a rapid transition without assessing withdrawal risk.'],[['Drug class','Antagonist'],['Before initiation','Appropriate opioid-free assessment'],['Planning','Analgesia and overdose prevention']],[OU])

q('After detoxification, a patient returns to a previously tolerated opioid dose. Why is overdose risk increased?', 'Loss of tolerance can make the former dose dangerously respiratory-depressant',[
 ('Detoxification creates permanent immunity to overdose','Tolerance and risk change after abstinence.'),('The prior dose is always safe if it was previously used','Past tolerance does not guarantee current safety.'),('Only injection exposure can cause fatal overdose','Other routes can also produce severe respiratory depression.')],
 'Reduced tolerance is a critical transition risk','**Abstinence can lower the dose needed for dangerous opioid effects.**',['Illicit potency variation and sedative combinations add risk.','Periods after hospital, prison or treatment transitions can be particularly vulnerable.'],'**Provide naloxone education and effective continuing treatment.**',['Discuss not using alone and avoiding sedative combinations within a harm-reduction plan.','Offer agonist treatment or other appropriate evidence-based options.'],[['Transition','Reduced tolerance'],['Risk','Former dose can be unsafe'],['Prevention','OUD treatment and rescue naloxone']],[OU],style='clinical_scenario')

q('A patient with stimulant intoxication has severe agitation, tachycardia and hyperthermia. Which initial drug class commonly helps control the hyperadrenergic state?', 'Benzodiazepines with monitored supportive care',[
 ('An SSRI as the immediate sedative','It does not provide rapid control and serotonergic interactions can be problematic.'),('A stimulant booster to prevent a crash','This can worsen the toxic state.'),('A long-term relapse medication as a substitute for acute cooling and resuscitation','Acute physiological danger needs immediate treatment.')],
 'Control excessive activity and sympathetic drive','**Sedation can reduce agitation and heat-producing muscle activity.**',['Cooling, fluids when appropriate and cardiac assessment are important.','Chest pain, seizures and rhabdomyolysis require targeted evaluation.'],'**Monitor airway, temperature and organ complications.**',['Use additional treatments according to persistent psychosis or other findings.','Do not attribute severe agitation to behavior alone.'],[['Acute state','Hyperadrenergic'],['Initial control','Monitored benzodiazepine treatment'],['Parallel care','Cooling and complication assessment']],[ST],style='clinical_scenario')

q('Which psychosocial intervention has particularly strong evidence and guideline support for stimulant-use disorder?', 'Contingency management',[
 ('Detoxification alone without continuing treatment','Withdrawal resolution does not address ongoing relapse risk.'),('Confrontational punishment as the evidence-based core method','This is not the recommended therapeutic mechanism.'),('An assurance that one licensed medication reliably cures all stimulant-use disorders','No universal pharmacological cure is established.')],
 'Reinforce recovery-related behavior','**Contingency management uses structured incentives linked to defined treatment goals.**',['It can be combined with CBT and community reinforcement approaches.','Access and implementation barriers should be addressed.'],'**Provide a comprehensive medical and psychosocial plan.**',['Selected off-label medications may be considered for defined situations by experienced clinicians.','Screen for opioid contamination risk and infectious/psychiatric complications.'],[['Core intervention','Contingency management'],['Combination','Other evidence-based psychosocial care'],['Medication','Selected context-dependent roles']],[ST])

q('After cessation of heavy stimulant use, a patient has fatigue, hypersomnia, dysphoria and anhedonia. Which assessment is especially important?', 'Evaluate depression, suicide risk, psychosis and medical complications during the withdrawal/recovery phase',[
 ('Assume the crash cannot have clinically important psychiatric risk','Mood deterioration can be severe.'),('Treat fatigue as proof of opioid intoxication without examining breathing or exposure','The syndrome needs a broader assessment.'),('Automatically restart illicit stimulants to normalize energy','This perpetuates exposure and risk rather than providing treatment.')],
 'A quieter phase can still carry serious risk','**Stimulant withdrawal can involve profound mood and reward-system symptoms.**',['The course and coexisting illness vary.','Persistent symptoms require reassessment rather than automatic attribution to withdrawal.'],'**Provide support, safety planning and continuing treatment.**',['Assess sleep, nutrition and the ability to care for oneself.','Investigate persistent psychosis or cardiovascular symptoms.'],[['Symptoms','Fatigue/dysphoria/anhedonia'],['Safety','Assess risk despite reduced agitation'],['Care','Support and ongoing treatment']],[ST],style='clinical_scenario')

q('What is the principal smoking-cessation mechanism of varenicline?', 'Partial agonism at alpha4beta2 nicotinic acetylcholine receptors',[
 ('Irreversible blockade of aldehyde dehydrogenase','This describes disulfiram’s relevant mechanism.'),('Pure mu-opioid receptor antagonism','This describes naltrexone.'),('Direct carbon monoxide chelation','It does not remove carbon monoxide from blood.')],
 'Reduce withdrawal while diminishing smoking reward','**Partial receptor stimulation can relieve craving and blunt nicotine reinforcement.**',['Discuss nausea, sleep effects and individual contraindication/dosing considerations.','Behavioral support improves the overall treatment plan.'],'**Offer an evidence-based cessation choice matched to preference and suitability.**',['Monitor mood or other symptoms as clinically indicated.','Review interacting medication exposure when smoke induction ceases.'],[['Target','Nicotinic receptor'],['Effect','Withdrawal/reward modulation'],['Care','Medication plus support']],[TO])

q('A smoker has persistent breakthrough cravings despite a nicotine patch. Which evidence-based option can be considered?', 'Combine the patch with an appropriate short-acting nicotine replacement product',[
 ('Stop all cessation treatment because any craving proves failure','Treatment can be optimized.'),('Use only reassurance and prohibit any dose review','Persistent craving can reflect inadequate coverage or behavioral triggers.'),('Treat nicotine replacement as inherently more harmful than continued combustible smoking','The combustion-related harm profile is very different.')],
 'Steady and rescue delivery can complement each other','**A patch provides background nicotine while a short-acting product can address breakthrough cravings.**',['Use appropriate dosing and technique.','Assess adverse effects and ongoing smoking exposure.'],'**Pair pharmacotherapy with a practical quit plan.**',['Identify triggers and arrange follow-up.','Review other cessation options if response or tolerability remains poor.'],[['Patch','Background delivery'],['Short acting','Breakthrough craving'],['Support','Behavioral plan and follow-up']],[TO],style='clinical_scenario')

q('Which symptom pattern is typical of nicotine withdrawal?', 'Irritability, craving, restlessness, poor concentration and increased appetite',[
 ('Delirium with a predictable high risk of withdrawal seizures','This is not the typical nicotine-withdrawal syndrome.'),('Profound respiratory depression with pinpoint pupils','This suggests opioid intoxication.'),('Progressive jaundice and coagulopathy as the defining withdrawal effect','These require another medical explanation.')],
 'Withdrawal syndromes differ in both symptoms and danger','**Nicotine withdrawal can be distressing and impair concentration without the usual alcohol-withdrawal complication pattern.**',['Symptoms can undermine a quit attempt.','Craving also has conditioned environmental components.'],'**Provide suitable medication and behavioral support.**',['Assess new severe symptoms rather than automatically attributing them to nicotine withdrawal.','Plan follow-up and relapse management without blame.'],[['Typical','Craving/irritability/appetite change'],['Not typical','Withdrawal delirium/seizures'],['Treatment','Cessation support and appropriate medication']],[TO])

if __name__=='__main__':finalize('Psychiatry',4,'Substance-use Disorders','psych-substance',rows,24)
